mapper.select:
select count(*)
from academic_grant_approvals aga
where aga.grant_application_id = #{grantApplicationId}
  and (
    aga.processed_by = #{handlerUserId}
    or exists (
        select 1
        from evaluation_organization_mappings eom
        where eom.user_id = #{handlerUserId}
          and eom.business_type = 'ACADEMIC_GRANT'
          and eom.data_scope in ('BUSINESS','ALL')
    )
  )
